<?php require_once dirname(__DIR__).'/core/bootstrap.php';require_admin();$title='لینک‌های VPN';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$url=trim($_POST['url']??'');$priority=(int)($_POST['priority']??0);$active=isset($_POST['active'])?1:0;if(!$name||!validate_http_url($url)){flash('error','نام و URL معتبر لازم است.');}else{if($id){$pdo->prepare('UPDATE subscriptions SET name=?,url=?,priority=?,active=?,updated_at=NOW() WHERE id=?')->execute([$name,$url,$priority,$active,$id]);}else{$pdo->prepare('INSERT INTO subscriptions(name,url,priority,active,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())')->execute([$name,$url,$priority,$active]);}flash('success','ذخیره شد.');}redirect('/admin/subscriptions.php');}
 if($action==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM subscriptions WHERE id=?')->execute([$id]);flash('success','حذف شد.');redirect('/admin/subscriptions.php');}
 if($action==='refresh'){$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT * FROM subscriptions WHERE id=?');$s->execute([$id]);$sub=$s->fetch();$r=$sub?refresh_subscription($pdo,$sub):['ok'=>false,'error'=>'Not found'];flash($r['ok']?'success':'error',$r['ok']?'رفرش شد؛ '.$r['count'].' نود پیدا شد.':'خطا: '.$r['error']);redirect('/admin/subscriptions.php');}
 if($action==='refresh_all'){$r=refresh_all_subscriptions($pdo,true);$ok=count(array_filter($r,fn($x)=>!empty($x['ok'])));flash('success',"رفرش تمام شد: {$ok} منبع موفق");redirect('/admin/subscriptions.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM subscriptions WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$list=$pdo->query('SELECT * FROM subscriptions ORDER BY priority DESC,id DESC')->fetchAll();require __DIR__.'/_header.php';?><div class="card"><h3><?=$edit?'ویرایش':'افزودن Subscription'?></h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="formgrid"><div><label>نام</label><input name="name" value="<?=e($edit['name']??'')?>" placeholder="Main Servers" required></div><div><label>اولویت</label><input name="priority" type="number" value="<?=e((string)($edit['priority']??0))?>"></div><div class="full"><label>Subscription URL</label><input name="url" type="url" value="<?=e($edit['url']??'')?>" required></div><div><label><input style="width:auto" type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> فعال</label></div><div><button>ذخیره</button></div></div></form></div><div class="card" style="margin-top:14px"><div class="actions" style="justify-content:space-between"><h3>منابع</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="refresh_all"><button class="btn secondary">رفرش همه</button></form></div><table><thead><tr><th>نام</th><th>نود</th><th>وضعیت</th><th>آخرین بررسی</th><th>عملیات</th></tr></thead><tbody><?php foreach($list as $s):?><tr><td><?=e($s['name'])?><br><span class="muted">Priority <?=e((string)$s['priority'])?></span></td><td><?=e((string)$s['node_count'])?></td><td><?php if(!$s['active']):?><span class="badge">خاموش</span><?php elseif($s['last_error']):?><span class="badge bad">خطا</span><br><small><?=e(text_substr($s['last_error'],0,100))?></small><?php else:?><span class="badge good">فعال</span><?php endif?></td><td><?=e($s['last_checked_at']??'-')?></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=$s['id']?>">ویرایش</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="refresh"><input type="hidden" name="id" value="<?=$s['id']?>"><button>رفرش</button></form><form method="post" onsubmit="return confirm('حذف شود؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn bad">حذف</button></form></div></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/_footer.php';
